@Entity(
  tableName = "book",
  foreignKeys = [ForeignKey(
    entity = AuthorEntity::class,
    parentColumns = ["id"],
    childColumns = ["authorId"],
    onDelete = ForeignKey.CASCADE
  )],
  indices = [Index("authorId")]          // without it every lookup is a full scan
)
