// One-to-many: a plain data class, not an @Entity
data class AuthorWithBooks(
  @Embedded val author: AuthorEntity,
  @Relation(parentColumn = "id", entityColumn = "authorId")
  val books: List<BookEntity>
)

@Dao
interface LibraryDao {
  // two queries underneath, so they must share one transaction
  @Transaction
  @Query("SELECT * FROM author WHERE id = :id")
  fun observeAuthor(id: Long): Flow<AuthorWithBooks?>

  // conditions across both tables: write the JOIN yourself
  @Query(
    "SELECT a.* FROM author a JOIN book b ON b.authorId = a.id " +
    "WHERE b.title LIKE :term GROUP BY a.id"
  )
  suspend fun authorsWritingAbout(term: String): List<AuthorEntity>
}

