class NoteDaoTest {
  private lateinit var db: AppDatabase
  private lateinit var dao: NoteDao

  @Before fun setUp() {
    db = Room.inMemoryDatabaseBuilder(
      ApplicationProvider.getApplicationContext(), AppDatabase::class.java
    ).build()
    dao = db.noteDao()
  }

  @After fun tearDown() { db.close() }

  @Test fun flow_reemits_after_insert() = runTest {
    dao.observeAll().test {                       // Turbine
      assertTrue(awaitItem().isEmpty())
      dao.upsert(NoteEntity(id = 1, title = "first", body = "", createdAt = 0))
      assertEquals("first", awaitItem().single().title)
    }
  }

  @Test fun deleting_an_author_cascades_to_books() = runTest {
    dao.insertAuthor(AuthorEntity(1, "Ada"))
    dao.insertBook(BookEntity(1, authorId = 1, title = "Notes"))
    dao.deleteAuthor(1)
    assertTrue(dao.allBooks().isEmpty())
  }
}

@RunWith(AndroidJUnit4::class)
class MigrationTest {
  @get:Rule
  val helper = MigrationTestHelper(
    InstrumentationRegistry.getInstrumentation(),
    AppDatabase::class.java
  )

  @Test fun migrate2To3_adds_column_and_keeps_rows() {
    helper.createDatabase(TEST_DB, 2).use { old ->
      // raw SQL: the version-2 entity classes no longer exist in the codebase
      old.execSQL("INSERT INTO note (id, title, body) VALUES (1, 'kept', 'body')")
    }

    val db = helper.runMigrationsAndValidate(TEST_DB, 3, true, MIGRATION_2_3)

    db.query("SELECT title, archived FROM note WHERE id = 1").use { c ->
      assertTrue(c.moveToFirst())
      assertEquals("kept", c.getString(0))   // schema validation would not catch data loss
      assertEquals(0, c.getInt(1))           // the new column took its default
    }
  }
}

@Entity(
  tableName = "message",
  indices = [
    Index(value = ["chatId", "createdAt"]),      // filter by chat, order by time
    Index(value = ["remoteId"], unique = true)
  ]
)
data class MessageEntity(
  @PrimaryKey(autoGenerate = true) val id: Long = 0,
  val chatId: Long,
  val remoteId: String,
  val createdAt: Long,
  val isRead: Boolean,
  val body: String,             // large: do not read it for a list screen
  val attachmentsJson: String   // converter-serialised, so never filter or sort on it
)

// Read only what the row actually draws
data class MessagePreview(val id: Long, val createdAt: Long, val snippet: String)

@Dao
interface MessageDao {
  // keyset pagination: constant time however deep the user scrolls
  @Query(
    "SELECT id, createdAt, substr(body, 1, 80) AS snippet FROM message " +
    "WHERE chatId = :chatId AND createdAt < :cursor " +
    "ORDER BY createdAt DESC LIMIT :limit"
  )
  suspend fun page(chatId: Long, cursor: Long, limit: Int): List<MessagePreview>

  // count in SQL, never by loading rows and taking .size
  @Query("SELECT COUNT(*) FROM message WHERE chatId = :chatId AND isRead = 0")
  fun observeUnread(chatId: Long): Flow<Int>

  // prove it: SCAN TABLE means no index was used
  @RawQuery
  suspend fun explain(query: SupportSQLiteQuery): List<String>
}

