class SessionCleaner @Inject constructor(
  private val db: AppDatabase,
  private val tokens: TokenStore,
  private val settings: DataStore<Preferences>,
  private val imageLoader: ImageLoader,
  private val httpCache: Cache,
  private val workManager: WorkManager,
  private val push: PushRegistrar
) {
  suspend fun logout() = withContext(Dispatchers.IO) {
    workManager.cancelAllWorkByTag(SYNC_TAG)     // stop the writers first
    push.unregister()                            // before the token is gone

    db.clearAllTables()
    tokens.clear()                               // at rest AND in memory
    settings.edit { prefs ->
      prefs.remove(USER_ID)
      prefs.remove(LAST_SYNC)                    // theme and onboarding stay: device-scoped
    }

    httpCache.evictAll()
    imageLoader.memoryCache?.clear()
    imageLoader.diskCache?.clear()
    context.cacheDir.resolve("exports").deleteRecursively()
  }
}

// Structural isolation: one database file per account
fun databaseFor(userId: String): AppDatabase =
  Room.databaseBuilder(context, AppDatabase::class.java, "app-" + userId + ".db").build()
